import{_ as l,a0 as r,w as o,s as d,I as a,x as n,a1 as i,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何使用 OpenSSL：哈希值、數字簽名等 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 OpenSSL：哈希值、數字簽名等 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 OpenSSL：哈希值、數字簽名等 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 OpenSSL：哈希值、數字簽名等 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20190620 How to use OpenSSL- Hashes, digital signatures, and more","title":"如何使用 OpenSSL：哈希值、數字簽名等","tag":"202008","desc":""},"relativePath":"202008/20190620 How to use OpenSSL- Hashes, digital signatures, and more.md","filePath":"[post].md"}'),u={name:"202008/20190620 How to use OpenSSL- Hashes, digital signatures, and more.md"};function g(h,s,b,c,k,y){const e=r("Link");return o(),d("div",null,[s[51]||(s[51]=a("h1",{id:"如何使用-openssl-哈希值、數字簽名等",tabindex:"-1"},[n("如何使用 OpenSSL：哈希值、數字簽名等 "),a("a",{class:"header-anchor",href:"#如何使用-openssl-哈希值、數字簽名等","aria-label":"Permalink to “如何使用 OpenSSL：哈希值、數字簽名等”"},"​")],-1)),s[52]||(s[52]=a("blockquote",null,[a("p",null,"通過 OpenSSL 深入瞭解密碼學的細節：哈希值、數字簽名、數字證書等。")],-1)),s[53]||(s[53]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202008/13/150012t7zwwk6x7wr69wih.jpg",alt:""})],-1)),a("p",null,[i(e,{href:"https://linux.cn/article-11810-1.html"},{default:p(()=>[...s[0]||(s[0]=[n("本系列的第一篇文章",-1)])]),_:1}),s[1]||(s[1]=n("通過 OpenSSL 庫和命令列實用程序介紹了哈希、加密/解密、數字簽名和數字證書。這第二篇文章將對細節進行深入探討。讓我們從計算中無處不在的哈希開始，並考慮是什麼使哈希函數",-1)),s[2]||(s[2]=a("em",null,"具備密碼學意義",-1)),s[3]||(s[3]=n("。",-1))]),s[54]||(s[54]=a("h3",{id:"密碼學哈希",tabindex:"-1"},[n("密碼學哈希 "),a("a",{class:"header-anchor",href:"#密碼學哈希","aria-label":"Permalink to “密碼學哈希”"},"​")],-1)),a("p",null,[s[5]||(s[5]=n("OpenSSL 源代碼的",-1)),i(e,{href:"https://www.openssl.org/source/"},{default:p(()=>[...s[4]||(s[4]=[n("下載頁面",-1)])]),_:1}),s[6]||(s[6]=n("包含了一個帶有最新版本的表格。每個版本都有兩個",-1)),s[7]||(s[7]=a("ruby",null,[n("哈希值"),a("rt",null,"hash")],-1)),s[8]||(s[8]=n("：160 位 SHA1 和 256 位 SHA256。這些值可以用來驗證下載的文件是否與存儲庫中的原始文件相匹配：下載者在本地重新計算下載文件的哈希值，然後將結果與原始文件進行比較。現代系統有計算這種哈希值的實用程序。例如，Linux 有 ",-1)),s[9]||(s[9]=a("code",null,"md5sum",-1)),s[10]||(s[10]=n(" 和 ",-1)),s[11]||(s[11]=a("code",null,"sha256sum",-1)),s[12]||(s[12]=n("。OpenSSL 本身也提供了類似的命令列實用程序。",-1))]),s[55]||(s[55]=t("<p>哈希值被用於計算的許多領域。例如，比特幣區塊鏈使用 SHA256 哈希值作為區塊標識符。挖比特幣就是生成一個低於指定閾值的 SHA256 哈希值，也就是至少有 N 個前導零的哈希值。（N 的值可以上升或下降，這取決於特定時間的挖礦生產力）。作為一個興趣點，如今的礦機是為並行生成 SHA256 哈希值而設計的硬件集羣。在 2018 年的一個高峯期，全球的比特幣礦工每秒產生約 7500 萬個<ruby>太哈希值<rt>terahash</rt></ruby> —— 這真是一個不可思議的數字。</p><p>網絡協議也使用哈希值（在這裏通常叫做“<ruby>校驗和<rt>checksum</rt></ruby>”）來支持消息的完整性；也就是説，保證收到的消息與發送的消息是一樣的。消息發送者計算消息的校驗和，並將結果與消息一起發送。當消息到達時，接收方重新計算校驗和。如果發送的校驗和與重新計算的校驗和不一致，那麼消息在傳輸過程中可能出現了一些問題，或者發送的校驗和出現了問題，或者兩者都出現了問題。在這種情況下，應該重新發送消息和它的校驗和，或者至少應該觸發一個錯誤情況。（如 UDP 這樣的低級網絡協議不會理會校驗和。）</p><p>哈希的其他例子大家都很熟悉。比如一個網站，要求用户用密碼進行驗證，用户在瀏覽器中輸入密碼，然後，他們通過 HTTPS 連接到服務器，密碼從瀏覽器加密發送到服務器。一旦密碼到達服務器，就會被解密，然後進行資料庫表的查詢。</p><p>在這個查詢表中應該存儲什麼？存儲密碼本身是有風險的。風險要小得多的方式是存儲一個由密碼生成的哈希值，也許在計算哈希值之前“加一些<ruby>鹽<rt>salt</rt></ruby>（額外的位）改善口味”。你的密碼可能會被髮送到 Web 服務器上，但網站可以向你保證，密碼不會存儲在那裏。</p>",4)),a("p",null,[s[14]||(s[14]=n("哈希值還出現在安全的各個領域。例如，",-1)),s[15]||(s[15]=a("ruby",null,[n("基於哈希值的消息認證碼"),a("rt",null,"hash-based message authentication code")],-1)),s[16]||(s[16]=n("（",-1)),i(e,{href:"https://en.wikipedia.org/wiki/HMAC"},{default:p(()=>[...s[13]||(s[13]=[n("HMAC",-1)])]),_:1}),s[17]||(s[17]=t("）使用一個哈希值和一個秘密的<ruby>加密密鑰<rt>cryptographic key</rt></ruby>來認證通過網絡發送的消息。HMAC 碼輕量級且易於在程序中使用，在 Web 服務中很受歡迎。一個 X509 數字證書包括一個稱為<ruby>指紋<rt>fingerprint</rt></ruby>的哈希值，它可以方便證書驗證。一個存放於內存中的<ruby>可信存儲<rt>truststore</rt></ruby>可以實現為一個以這種指紋為鍵的查找表 —— 作為一個支持恆定查找時間的<ruby>哈希映射<rt>hash map</rt></ruby>。來自傳入的證書的指紋可以與可信存儲中的密鑰進行比較，以確定是否匹配。",9))]),s[56]||(s[56]=t(`<p><ruby>密碼學哈希函數<rt>cryptographic hash function</rt></ruby>應該具有什麼特殊屬性？它應該是<ruby>單向<rt>one-way</rt></ruby>的，這意味着很難被逆轉。一個加密哈希函數應該是比較容易計算的，但是計算它的反函數（將哈希值映射回輸入位串的函數）在計算上應該是困難的。下面是一個描述，用 <code>chf</code> 作為加密哈希函數，我的密碼 <code>foobar</code> 作為樣本輸入。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>        +---+</span></span>
<span class="line"><span>foobar—&gt;|chf|—&gt;hash value ## 簡單直接</span></span>
<span class="line"><span>        +--–+</span></span></code></pre></div><p>相比之下，逆向操作是不可行的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>            +-----------+</span></span>
<span class="line"><span>hash value—&gt;|chf inverse|—&gt;foobar ## 棘手困難</span></span>
<span class="line"><span>            +-----------+</span></span></code></pre></div>`,4)),a("p",null,[s[20]||(s[20]=n("例如，回憶一下 SHA256 哈希函數。對於一個任意長度為 N > 0 的輸入位串，這個函數會生成一個 256 位的固定長度的哈希值；因此，這個哈希值甚至不會反映出輸入位串的長度 N，更不用説字符串中每個位的值了。順便説一下，SHA256 不容易受到",-1)),a("ruby",null,[i(e,{href:"https://en.wikipedia.org/wiki/Length_extension_attack"},{default:p(()=>[...s[18]||(s[18]=[n("長度擴展攻擊",-1)])]),_:1}),s[19]||(s[19]=a("rt",null,"length extension attack",-1))]),s[21]||(s[21]=n("。唯一有效的逆向工程方法是通過蠻力搜索將計算出的 SHA256 哈希值逆向返回到輸入位串，這意味着需要嘗試所有可能的輸入位串，直到找到與目標哈希值匹配的位串。這樣的搜索在 SHA256 這樣一個完善的加密哈希函數上是不可行的。",-1))]),a("p",null,[s[23]||(s[23]=n("現在，最後一個回顧的知識點是",-1)),s[24]||(s[24]=a("ruby",null,[n("有序"),a("rt",null,"in order")],-1)),s[25]||(s[25]=n("。加密哈希值是統計學上的唯一，而不是無條件的唯一，這意味着兩個不同的輸入位串產生相同的哈希值是不太可能的，但也不是不可能的 —— 這稱之為",-1)),s[26]||(s[26]=a("ruby",null,[n("碰撞"),a("rt",null,"collision")],-1)),s[27]||(s[27]=n("。",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Birthday_problem"},{default:p(()=>[...s[22]||(s[22]=[n("生日問題",-1)])]),_:1}),s[28]||(s[28]=n("提供了一個很好的反直覺的碰撞例子。對各種哈希算法的",-1)),s[29]||(s[29]=a("ruby",null,[n("抗碰撞性"),a("rt",null,"collision resistance")],-1)),s[30]||(s[30]=n("有着廣泛的研究。例如，MD5（128 位哈希值）在大約 2^21 次哈希之後，抗碰撞能力就會崩潰。對於 SHA1（160 位哈希值），大約在 2^61 次哈希後開始崩潰。",-1))]),s[57]||(s[57]=t(`<p>對於 SHA256 的抗碰撞能力的剖析，目前還沒有一個很好的估計。這個事實並不奇怪。SHA256 有 2^256 個不同的哈希值範圍，這個數字的十進制表示法有 78 位之多! 那麼，SHA256 哈希會不會發生碰撞呢？當然可能，但可能性極小。</p><p>在下面的命令列示例中，有兩個輸入文件被用作位串源：<code>hashIn1.txt</code> 和 <code>hashIn2.txt</code>。第一個文件包含 <code>abc</code>，第二個文件包含 <code>1a2b3c</code>。</p><p>為了便於閲讀，這些文件包含的是文本，但也可以使用二進制文件代替。</p><p>在命令列（百分號 <code>%</code> 是提示符）使用 Linux <code>sha256sum</code> 實用程序對這兩個文件進行處理產生以下哈希值（十六進制）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>% sha256sum hashIn1.txt</span></span>
<span class="line"><span>9e83e05bbf9b5db17ac0deec3b7ce6cba983f6dc50531c7a919f28d5fb3696c3 hashIn1.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% sha256sum hashIn2.txt</span></span>
<span class="line"><span>3eaac518777682bf4e8840dd012c0b104c2e16009083877675f00e995906ed13 hashIn2.txt</span></span></code></pre></div><p>OpenSSL 哈希對應的結果與預期相同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>% openssl dgst -sha256 hashIn1.txt</span></span>
<span class="line"><span>SHA256(hashIn1.txt)= 9e83e05bbf9b5db17ac0deec3b7ce6cba983f6dc50531c7a919f28d5fb3696c3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% openssl dgst -sha256 hashIn2.txt</span></span>
<span class="line"><span>SHA256(hashIn2.txt)= 3eaac518777682bf4e8840dd012c0b104c2e16009083877675f00e995906ed13</span></span></code></pre></div><p>這種對密碼學哈希函數的研究，為我們仔細研究數字簽名及其與密鑰對的關係奠定了基礎。</p><h3 id="數字簽名" tabindex="-1">數字簽名 <a class="header-anchor" href="#數字簽名" aria-label="Permalink to “數字簽名”">​</a></h3><p>顧名思義，<ruby>數字簽字<rt>digital signature</rt></ruby>可以附在文件或其他一些電子<ruby>工件<rt>artifact</rt></ruby>（如程序）上，以證明其真實性。因此，這種簽名類似於紙質文件上的手寫簽名。驗證數字簽名就是要確認兩件事：第一，被擔保的工件在簽名被附上後沒有改變，因為它部分是基於文件的加密學哈希值。第二，簽名屬於一個人（例如 Alice），只有她才能獲得一對密鑰中的私鑰。順便説一下，對代碼（源碼或編譯後的代碼）進行數字簽名已經成為程序員的普遍做法。</p><p>讓我們來了解一下數字簽名是如何創建的。如前所述，沒有公鑰和私鑰對就沒有數字簽名。當使用 OpenSSL 創建這些密鑰時，有兩個獨立的命令：一個是創建私鑰，另一個是從私鑰中提取匹配的公鑰。這些密鑰對用 base64 編碼，在這個過程中可以指定它們的大小。</p><p><ruby>私鑰<rt>private key</rt></ruby>由數值組成，其中兩個數值（一個<ruby>模數<rt>modulus</rt></ruby>和一個<ruby>指數<rt>exponent</rt></ruby>）組成了公鑰。雖然私鑰文件包含了<ruby>公鑰<rt>public key</rt></ruby>，但提取出來的公鑰並<strong>不會</strong>透露相應私鑰的值。</p><p>因此，生成的帶有私鑰的文件包含了完整的密鑰對。將公鑰提取到自己的文件中是很實用的，因為這兩把鑰匙有不同的用途，而這種提取方式也將私鑰可能被意外公開的危險降到最低。</p><p>接下來，這對密鑰的私鑰被用來生成目標工件（如電子郵件）的哈希值，從而創建簽名。在另一端，接收者的系統使用這對密鑰的公鑰來驗證附在工件上的簽名。</p><p>現在舉個例子。首先，用 OpenSSL 生成一個 2048 位的 RSA 密鑰對：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl genpkey -out privkey.pem -algorithm rsa 2048</span></span></code></pre></div><p>在這個例子中，我們可以捨去 <code>-algorithm rsa</code> 標誌，因為 <code>genpkey</code> 默認為 RSA 類型。文件的名稱（<code>privkey.pem</code>）是任意的，但是<ruby>隱私增強郵件<rt>Privacy Enhanced Mail</rt></ruby>（PEM）擴展名 <code>.pem</code> 是默認 PEM 格式的慣用擴展名。（如果需要的話，OpenSSL 有命令可以在各種格式之間進行轉換。）如果需要更大的密鑰大小（例如 4096），那麼最後一個參數 <code>2048</code> 可以改成 <code>4096</code>。這些大小總是二的冪。</p><p>下面是產生的 <code>privkey.pem</code> 文件的一個片斷，它是 base64 編碼的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-----BEGIN PRIVATE KEY-----</span></span>
<span class="line"><span>MIICdgIBADANBgkqhkiG9w0BAQEFAASCAmAwggJcAgEAAoGBANnlAh4jSKgcNj/Z</span></span>
<span class="line"><span>JF4J4WdhkljP2R+TXVGuKVRtPkGAiLWE4BDbgsyKVLfs2EdjKL1U+/qtfhYsqhkK</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>-----END PRIVATE KEY-----</span></span></code></pre></div><p>接下來的命令就會從私鑰中提取出這對密鑰的公鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl rsa -in privkey.pem -outform PEM -pubout -out pubkey.pem</span></span></code></pre></div><p>由此產生的 <code>pubkey.pem</code> 文件很小，可以在這裏完整地顯示出來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-----BEGIN PUBLIC KEY-----</span></span>
<span class="line"><span>MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDZ5QIeI0ioHDY/2SReCeFnYZJY</span></span>
<span class="line"><span>z9kfk11RrilUbT5BgIi1hOAQ24LMilS37NhHYyi9VPv6rX4WLKoZCmkeYaWk/TR5</span></span>
<span class="line"><span>4nbH1E/AkniwRoXpeh5VncwWMuMsL5qPWGY8fuuTE27GhwqBiKQGBOmU+MYlZonO</span></span>
<span class="line"><span>O0xnAKpAvysMy7G7qQIDAQAB</span></span>
<span class="line"><span>-----END PUBLIC KEY-----</span></span></code></pre></div><p>現在，有了密鑰對，數字簽名就很容易了 —— 在本例中，源文件 <code>client.c</code> 是要簽名的工件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl dgst -sha256 -sign privkey.pem -out sign.sha256 client.c</span></span></code></pre></div><p><code>client.c</code> 源文件的摘要是 SHA256，私鑰在前面創建的 <code>privkey.pem</code> 文件中。由此產生的二進制簽名文件是 <code>sign.sha256</code>，這是一個任意的名字。要得到這個文件的可讀版本（比如 base64），後續命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl enc -base64 -in sign.sha256 -out sign.sha256.base64</span></span></code></pre></div><p>文件 <code>sign.sha256.base64</code> 現在包含如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>h+e+3UPx++KKSlWKIk34fQ1g91XKHOGFRmjc0ZHPEyyjP6/lJ05SfjpAJxAPm075</span></span>
<span class="line"><span>VNfFwysvqRGmL0jkp/TTdwnDTwt756Ej4X3OwAVeYM7i5DCcjVsQf5+h7JycHKlM</span></span>
<span class="line"><span>o/Jd3kUIWUkZ8+Lk0ZwzNzhKJu6LM5KWtL+MhJ2DpVc=</span></span></code></pre></div><p>或者，可執行文件 <code>client</code> 也可以被簽名，由此產生的 base64 編碼簽名將如預期的不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>VMVImPgVLKHxVBapJ8DgLNJUKb98GbXgehRPD8o0ImADhLqlEKVy0HKRm/51m9IX</span></span>
<span class="line"><span>xRAN7DoL4Q3uuVmWWi749Vampong/uT5qjgVNTnRt9jON112fzchgEoMb8CHNsCT</span></span>
<span class="line"><span>XIMdyaPtnJZdLALw6rwMM55MoLamSc6M/MV1OrJnk/g=</span></span></code></pre></div><p>這一過程的最後一步是用公鑰驗證數字簽名。作為驗證的一個重要步驟，應重新計算用於簽署工件（在本例中，是可執行的 <code>client</code> 程序）的哈希值，因為驗證過程應表明工件在簽署後是否發生了變化。</p><p>有兩個 OpenSSL 命令用於這個目的。第一條命令是對 base64 簽名進行解碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl enc -base64 -d -in sign.sha256.base64 -out sign.sha256</span></span></code></pre></div><p>第二條是核實簽名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl dgst -sha256 -verify pubkey.pem -signature sign.sha256 client</span></span></code></pre></div><p>第二條命令的輸出，應該是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Verified OK</span></span></code></pre></div><p>為了瞭解驗證失敗時的情況，一個簡短但有用的練習是將最後一個 OpenSSL 命令中的可執行的 <code>client</code> 文件替換為源文件 <code>client.c</code>，然後嘗試驗證。另一個練習是改變 <code>client</code> 程序，無論多麼輕微，然後再試一次。</p><h3 id="數字證書" tabindex="-1">數字證書 <a class="header-anchor" href="#數字證書" aria-label="Permalink to “數字證書”">​</a></h3><p><ruby>數字證書<rt>digital certificate</rt></ruby>彙集了到目前為止所分析的各個部分：哈希值、密鑰對、數字簽名和加密/解密。生產級證書的第一步是創建一個<ruby>證書籤名請求<rt>certificate signing request</rt></ruby>（CSR），然後將其發送給<ruby>證書頒發機構<rt>certificate authority</rt></ruby>（CA）。在 OpenSSL 的例子中，要做到這一點，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl req -out myserver.csr -new -newkey rsa:4096 -nodes -keyout myserverkey.pem</span></span></code></pre></div><p>這個例子生成了一個 CSR 文檔，並將該文檔存儲在文件 <code>myserver.csr</code>（base64 文本）中。這裏的目的是：CSR 文檔要求 CA 保證與指定域名相關聯的身份，域名也就是 CA 所説的<ruby>通用名<rt>common name</rt></ruby>（CN）。</p><p>儘管可以使用現有的密鑰對，但這個命令也會生成一個新的密鑰對。請注意，在諸如 <code>myserver.csr</code> 和 <code>myserverkey.pem</code> 等名稱中使用 <code>server</code> 暗示了數字證書的典型用途：作為與 www.google.com 等域名相關的 Web 服務器的身份擔保。</p><p>然而，無論數字證書如何使用，同樣使用這個命令都會創建一個 CSR。它還會啓動一個問題/回答的交互式會話，提示有關域名的相關信息，以便與請求者的數字證書相連接。這個交互式會話可以通過在命令中提供基本的信息，用反斜槓來續行一步完成。<code>-subj</code> 標誌提供了所需的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>% openssl req -new \\</span></span>
<span class="line"><span>-newkey rsa:2048 -nodes -keyout privkeyDC.pem \\</span></span>
<span class="line"><span>-out myserver.csr \\</span></span>
<span class="line"><span>-subj &quot;/C=US/ST=Illinois/L=Chicago/O=Faulty Consulting/OU=IT/CN=myserver.com&quot;</span></span></code></pre></div><p>產生的 CSR 文件在發送給 CA 之前可以進行檢查和驗證。這個過程可以創建具有所需格式（如 X509）、簽名、有效期等的數字證書。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl req -text -in myserver.csr -noout -verify</span></span></code></pre></div><p>這是輸出的一個片斷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>verify OK</span></span>
<span class="line"><span>Certificate Request:</span></span>
<span class="line"><span>Data:</span></span>
<span class="line"><span>Version: 0 (0x0)</span></span>
<span class="line"><span>Subject: C=US, ST=Illinois, L=Chicago, O=Faulty Consulting, OU=IT, CN=myserver.com</span></span>
<span class="line"><span>Subject Public Key Info:</span></span>
<span class="line"><span>Public Key Algorithm: rsaEncryption</span></span>
<span class="line"><span>Public-Key: (2048 bit)</span></span>
<span class="line"><span>Modulus:</span></span>
<span class="line"><span>00:ba:36:fb:57:17:65:bc:40:30:96:1b:6e:de:73:</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>Exponent: 65537 (0x10001)</span></span>
<span class="line"><span>Attributes:</span></span>
<span class="line"><span>a0:00</span></span>
<span class="line"><span>Signature Algorithm: sha256WithRSAEncryption</span></span>
<span class="line"><span>…</span></span></code></pre></div><h3 id="自簽證書" tabindex="-1">自簽證書 <a class="header-anchor" href="#自簽證書" aria-label="Permalink to “自簽證書”">​</a></h3><p>在開發 HTTPS 網站的過程中，手頭有一個不用經過 CA 流程的數字證書是很方便的。在 HTTPS 握手的認證階段，<ruby>自簽證書<rt>self-signed certificate</rt></ruby>就能滿足要求，儘管任何現代瀏覽器都會警告説這樣的證書毫無價值。繼續這個例子，自簽證書的 OpenSSL 命令（有效期為一年，使用 RSA 公鑰）如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl req -x509 -sha256 -nodes -days 365 -newkey rsa:4096 -keyout myserver.pem -out myserver.crt</span></span></code></pre></div><p>下面的 OpenSSL 命令呈現了生成的證書的可讀版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl x509 -in myserver.crt -text -noout</span></span></code></pre></div><p>這是自簽證書的部分輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Certificate:</span></span>
<span class="line"><span>Data:</span></span>
<span class="line"><span>Version: 3 (0x2)</span></span>
<span class="line"><span>Serial Number: 13951598013130016090 (0xc19e087965a9055a)</span></span>
<span class="line"><span>Signature Algorithm: sha256WithRSAEncryption</span></span>
<span class="line"><span>Issuer: C=US, ST=Illinois, L=Chicago, O=Faulty Consulting, OU=IT, CN=myserver.com</span></span>
<span class="line"><span>Validity</span></span>
<span class="line"><span>Not Before: Apr 11 17:22:18 2019 GMT</span></span>
<span class="line"><span>Not After : Apr 10 17:22:18 2020 GMT</span></span>
<span class="line"><span>Subject: C=US, ST=Illinois, L=Chicago, O=Faulty Consulting, OU=IT, CN=myserver.com</span></span>
<span class="line"><span>Subject Public Key Info:</span></span>
<span class="line"><span>Public Key Algorithm: rsaEncryption</span></span>
<span class="line"><span>Public-Key: (4096 bit)</span></span>
<span class="line"><span>Modulus:</span></span>
<span class="line"><span>00:ba:36:fb:57:17:65:bc:40:30:96:1b:6e:de:73:</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Exponent: 65537 (0x10001)</span></span>
<span class="line"><span>X509v3 extensions:</span></span>
<span class="line"><span>X509v3 Subject Key Identifier:</span></span>
<span class="line"><span>3A:32:EF:3D:EB:DF:65:E5:A8:96:D7:D7:16:2C:1B:29:AF:46:C4:91</span></span>
<span class="line"><span>X509v3 Authority Key Identifier:</span></span>
<span class="line"><span>keyid:3A:32:EF:3D:EB:DF:65:E5:A8:96:D7:D7:16:2C:1B:29:AF:46:C4:91</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        X509v3 Basic Constraints:</span></span>
<span class="line"><span>            CA:TRUE</span></span>
<span class="line"><span>Signature Algorithm: sha256WithRSAEncryption</span></span>
<span class="line"><span>     3a:eb:8d:09:53:3b:5c:2e:48:ed:14:ce:f9:20:01:4e:90:c9:</span></span>
<span class="line"><span>     ...</span></span></code></pre></div>`,57)),a("p",null,[s[32]||(s[32]=n("如前所述，RSA 私鑰包含的值是用來生成公鑰的。但是，給定的公鑰",-1)),s[33]||(s[33]=a("strong",null,"不會",-1)),s[34]||(s[34]=n("泄露匹配的私鑰。關於底層數學理論的介紹，見 ",-1)),i(e,{href:"https://simple.wikipedia.org/wiki/RSA_algorithm"},{default:p(()=>[...s[31]||(s[31]=[n("https://simple.wikipedia.org/wiki/RSA_algorithm",-1)])]),_:1}),s[35]||(s[35]=n("。",-1))]),s[58]||(s[58]=t(`<p>數字證書與用於生成該證書的密鑰對之間存在着重要的對應關係，即使證書只是自籤的：</p><ul><li>數字證書包含構成公鑰的指數和模數值。這些值是最初生成的 PEM 文件中密鑰對的一部分，在本例中，是文件 <code>myserver.pem</code>。</li><li><ruby>指數<rt>exponent</rt></ruby>幾乎總是 65,537（如本例中），所以可以忽略。</li><li>密鑰對的<ruby>模數<rt>modulus</rt></ruby>應該與數字證書的模數相匹配。</li></ul><p>模數是一個很大的值，為了便於閲讀，可以進行哈希處理。下面是兩個 OpenSSL 命令，它們檢查相同的模數，從而確認數字證書是基於 PEM 文件中的密鑰對。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>% openssl x509 -noout -modulus -in myserver.crt | openssl sha1 ## 證書中的模數</span></span>
<span class="line"><span>(stdin)= 364d21d5e53a59d482395b1885aa2c3a5d2e3769</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% openssl rsa -noout -modulus -in myserver.pem | openssl sha1 ## 密鑰中的模數</span></span>
<span class="line"><span>(stdin)= 364d21d5e53a59d482395b1885aa2c3a5d2e3769</span></span></code></pre></div><p>所產生的哈希值匹配，從而確認數字證書是基於指定的密鑰對。</p><h3 id="回到密鑰分發問題上" tabindex="-1">回到密鑰分發問題上 <a class="header-anchor" href="#回到密鑰分發問題上" aria-label="Permalink to “回到密鑰分發問題上”">​</a></h3><p>讓我們回到第一部分末尾提出的一個問題：<code>client</code> 程序和 Google Web 服務器之間的 TLS 握手。握手協議有很多種，即使是用在 <code>client</code> 例子中的 Diffie-Hellman 版本也有不同的方式。儘管如此，<code>client</code> 例子遵循了一個共同的模式。</p><p>首先，在 TLS 握手過程中，<code>client</code> 程序和 Web 服務器就<ruby>加密套件<rt>cipher suite</rt></ruby>達成一致，其中包括要使用的算法。在本例中，該套件是 <code>ECDHE-RSA-AES128-GCM-SHA256</code>。</p><p>現在值得關注的兩個要素是 RSA 密鑰對算法和 AES128 塊密碼，用於在握手成功的情況下對消息進行加密和解密。關於加密/解密，這個過程有兩種流派：<ruby>對稱<rt>symmetric</rt></ruby>和<ruby>非對稱<rt>asymmetric</rt></ruby>。在對稱流派中，加密和解密使用的是<em>相同的</em>密鑰，這首先就引出了<ruby>密鑰分發問題<rt>key distribution problem</rt></ruby>。如何將密鑰安全地分發給雙方？在非對稱流派中，一個密鑰用於加密（在這種情況下，是 RSA 公鑰），但另一個密鑰用於解密（在這種情況下，是來自同一對密鑰的 RSA 私鑰）。</p><p><code>client</code> 程序擁有來認證證書的 Google Web 服務器的公鑰，而 Web 服務器擁有來自同一對密鑰的私鑰。因此，<code>client</code> 程序可以向 Web 服務器發送加密信息，而 Web 服務器可以單獨對該通信進行解密。</p><p>在 TLS 的情況下，對稱方式有兩個顯著的優勢：</p><ul><li>在 <code>client</code> 程序與 Google Web 服務器之間的互動中，認證是單向的。Google Web 服務器向 <code>client</code> 程序發送三張證書，但 <code>client</code> 程序並沒有向 Web 服務器發送證書，因此，Web 服務器沒有來自客户端的公鑰，無法加密發給客户端的消息。</li><li>使用 AES128 的對稱加密/解密比使用 RSA 密鑰的非對稱加密/解密快了<strong>近千倍</strong>。</li></ul><p>TLS 握手將兩種加密/解密方式巧妙地結合在一起。在握手過程中，<code>client</code> 程序會生成隨機位，即所謂的<ruby>預主密<rt>pre-master secret</rt></ruby>（PMS）。然後，<code>client</code> 程序用服務器的公鑰對 PMS 進行加密，並將加密後的 PMS 發送給服務器，服務器再用 RSA 密鑰對的私鑰對 PMS 信息進行解密：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>              +-------------------+ encrypted PMS  +--------------------+</span></span>
<span class="line"><span>client PMS---&gt;|server’s public key|---------------&gt;|server’s private key|---&gt;server PMS</span></span>
<span class="line"><span>              +-------------------+                +--------------------+</span></span></code></pre></div><p>在這個過程結束時，<code>client</code> 程序和 Google Web 服務器現在擁有相同的 PMS 位。每一方都使用這些位生成一個<ruby>主密碼<rt>master secret</rt></ruby>，並立即生成一個稱為<ruby>會話密鑰<rt>session key</rt></ruby>的對稱加密/解密密鑰。現在有兩個不同但等價的會話密鑰，連接的每一方都有一個。在 <code>client</code> 的例子中，會話密鑰是 AES128 類的。一旦在 <code>client</code> 程序和 Google Web 服務器兩邊生成了會話密鑰，每一邊的會話密鑰就會對雙方的對話進行保密。如果任何一方（例如，<code>client</code> 程序）或另一方（在這種情況下，Google Web 服務器）要求重新開始握手，握手協議（如 Diffie-Hellman）允許整個 PMS 過程重複進行。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在命令列上説明的 OpenSSL 操作也可以通過底層庫的 API 完成。這兩篇文章重點使用了這個實用程序，以保持例子的簡短，並專注於加密主題。如果你對安全問題感興趣，OpenSSL 是一個很好的開始地方，並值得深入研究。</p><hr>`,18)),a("p",null,[s[37]||(s[37]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/19/6/cryptography-basics-openssl-part-2"},{default:p(()=>[...s[36]||(s[36]=[n("https://opensource.com/article/19/6/cryptography-basics-openssl-part-2",-1)])]),_:1})]),a("p",null,[s[42]||(s[42]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/mkalindepauledu"},{default:p(()=>[...s[38]||(s[38]=[n("Marty Kalin",-1)])]),_:1}),s[43]||(s[43]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[39]||(s[39]=[n("lujun9972",-1)])]),_:1}),s[44]||(s[44]=n(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[40]||(s[40]=[n("wxy",-1)])]),_:1}),s[45]||(s[45]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[41]||(s[41]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[48]||(s[48]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[46]||(s[46]=[n("LCTT",-1)])]),_:1}),s[49]||(s[49]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[47]||(s[47]=[n("Linux中國",-1)])]),_:1}),s[50]||(s[50]=n(" 榮譽推出",-1))])])}const C=l(u,[["render",g]]);export{S as __pageData,C as default};
